changeSet.sql:
ALTER TABLE payouts ADD COLUMN part_number integer NOT NULL DEFAULT 1;
ALTER TABLE payouts ADD COLUMN part_count integer NOT NULL DEFAULT 1;
ALTER TABLE payouts ADD CONSTRAINT chk_payouts_part
    CHECK (part_count >= 1 AND part_number BETWEEN 1 AND part_count);
DROP INDEX uq_payouts_one_live_per_sale;
CREATE UNIQUE INDEX uq_payouts_one_live_per_part ON payouts (transaction_id, part_number)
    WHERE status IN ('SENDING', 'AWAITING_OTP', 'PENDING', 'SUCCESS') AND deleted = false;
COMMENT ON COLUMN payouts.part_count IS
    'How many equal parts the sale is paid in (Paystack caps one transfer). Fixed once a part has been paid.';

changeSet.rollback:
DROP INDEX uq_payouts_one_live_per_part;
CREATE UNIQUE INDEX uq_payouts_one_live_per_sale ON payouts (transaction_id)
    WHERE status IN ('SENDING', 'AWAITING_OTP', 'PENDING', 'SUCCESS') AND deleted = false;
ALTER TABLE payouts DROP CONSTRAINT chk_payouts_part;
ALTER TABLE payouts DROP COLUMN part_count;
ALTER TABLE payouts DROP COLUMN part_number;
